class Solution {
public:
    bool canConstruct(string ransomNote, string magazine) {
        map<char, int> cnt;
        for (char c : magazine) cnt[c]++;
        for (int i = 0; i < (int)ransomNote.size(); i++) {
            if (--cnt[ransomNote[i]] < 0) return false;
        }
        return true;
    }
};
